using System;
using System.IO;
using System.Linq;
using System.Collections;
using System.Collections.Generic;
using System.Reflection;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
using UnityEngine.UI;
using Object=UnityEngine.Object;

[InitializeOnLoad] public static class EscalaPresentacionProbe
{
 const string K="EscalaPresentacionProbe.Active", O="C:/Caballos/Validation/EscalaFinal/";
 const BindingFlags F=BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.Instance;
 static IEnumerator tests; static List<string> checks=new();
 static EscalaPresentacionProbe(){EditorApplication.update+=Step;}
 public static void Run(){if(!Application.isBatchMode||string.IsNullOrEmpty(Environment.GetEnvironmentVariable("CABALLOS_VALIDATION_SAVE_PATH")))throw new Exception("Copia aislada requerida");Directory.CreateDirectory(O);EditorSceneManager.OpenScene(GameLaunch.HubScenePath);EditorApplication.delayCall+=()=>{SessionState.SetBool(K,true);EditorApplication.isPlaying=true;};}
 static void Step(){if(!SessionState.GetBool(K,false)||!EditorApplication.isPlaying)return;try{tests??=Tests();if(!tests.MoveNext())End(0);}catch(Exception e){Debug.LogException(e);End(1);}}
 static IEnumerator Tests(){while(GameManager.Instancia==null||GameManager.Instancia.caballosJugador.Count==0)yield return null;
 foreach(var id in CatalogoCaballos.Todos){var h=new Caballo();CatalogoCaballos.Asignar(h,id);var root=new GameObject("ActorPrueba",typeof(RectTransform));var child=new GameObject("Sprite",typeof(RectTransform),typeof(Image));child.transform.SetParent(root.transform,false);var img=child.GetComponent<Image>();var a=root.AddComponent<HorseVisualAnimator>();a.enabled=false;a.Bind(h,img,true);var p=a.Profile;Check(p!=null&&p.IsValid&&p.catalogIdentityId==id.id,"Perfil propio "+id.id);var b=PresentacionCaballoCarrera.Limites(p);Check(b.width>0&&b.height>0&&b.width<=1&&b.height<=1,"Límites medidos válidos "+id.id);var rect=img.rectTransform;var size=rect.sizeDelta;var pivot=rect.pivot;var pos=rect.anchoredPosition;
 Check(Mathf.Abs(size.y*b.height-148)<.01f&&Mathf.Abs(size.x/size.y-p.runFrames[0].rect.width/p.runFrames[0].rect.height)<.0001f,"148 unidades sin deformar "+id.id);Check(img.sprite==p.runFrames[2],"Previa misma lámina "+id.id);a.StartRun();
 for(int i=0;i<8;i++){typeof(HorseVisualAnimator).GetField("elapsed",F).SetValue(a,i/p.framesPerSecond+.01f-Time.deltaTime);Call(a,"Update");Check(img.sprite==p.runFrames[i]&&rect.sizeDelta==size&&rect.pivot==pivot&&rect.anchoredPosition==pos&&rect.localScale==Vector3.one,"Fase sin resize "+id.id+"/"+i);}
 a.StopRun();Check(img.sprite==p.runFrames[2]&&rect.sizeDelta==size&&img.GetComponentInParent<RectMask2D>()!=null,"Llegada misma escala y máscara "+id.id);Object.DestroyImmediate(root);}
 var g=GameManager.Instancia; var legacyRoot=new GameObject("LegacyPrueba",typeof(RectTransform)); var legacyImage=new GameObject("Sprite",typeof(RectTransform),typeof(Image)).GetComponent<Image>();legacyImage.transform.SetParent(legacyRoot.transform,false);var legacyHorse=new Caballo{visualProfileId="legacy:0",sprite=g.spritesCaballos[0]};var legacyAnimator=legacyRoot.AddComponent<HorseVisualAnimator>();legacyAnimator.Bind(legacyHorse,legacyImage,true);legacyAnimator.StartRun();legacyAnimator.StopRun();Check(legacyAnimator.Profile==null&&legacyImage.sprite==legacyHorse.sprite&&legacyImage.rectTransform.anchorMin==Vector2.zero&&legacyImage.rectTransform.anchorMax==Vector2.one,"Legacy sin animación conserva sprite y layout");Object.DestroyImmediate(legacyRoot);
 foreach(int count in new[]{5,6,8}){g.VolverAlHub();yield return null;g.IniciarNuevaPartida();g.dinero=10000;Check(g.ElegirCarrera(g.ObtenerOfertaCarreras()[0].id,out _),"Prepara carrera "+count);var race=g.ObtenerCarreraProgramada();while(race.participantes.Count>count)race.participantes.RemoveAt(race.participantes.Count-1);while(race.participantes.Count<count){var p=JsonUtility.FromJson<ParticipanteCarrera>(JsonUtility.ToJson(race.participantes.Last()));p.caballo.id=Guid.NewGuid().ToString("N");p.caballo.esDelJugador=false;race.participantes.Add(p);}var own=race.participantes.Single(p=>p.caballo.esDelJugador);race.participantes.Remove(own);race.participantes.Insert(1,own);foreach(var p in race.participantes){p.caballo.velocidad=p.caballo.stamina=p.caballo.inteligencia=p.caballo.esDelJugador?16:3;}
 UIManager.instance.viewCarrera.GetComponentInChildren<CarreraUI>(true).enabled=true;g.SetState(Interactable.Tipo.TV);yield return null;var ui=UIManager.instance.viewCarrera.GetComponentInChildren<CarreraUI>();ui.enabled=false;var actors=(List<RectTransform>)Get(ui,"caballosUI");var anim=(List<HorseVisualAnimator>)Get(ui,"visualAnimators");foreach(var a in anim)a.enabled=false;var view=Get(ui,"pista");var world=(RectTransform)Get(view,"mundo");var vp=(RectTransform)Get(view,"viewport");var map=(MapaPistaCarrera)Get(view,"mapa");
 Check(actors.Count==count&&actors.All(a=>a.localScale==Vector3.one),"Actores escala uniforme "+count);Check(!ui.contenedorCaballos.GetComponentsInChildren<Graphic>(true).Any(x=>x.name=="PuntoCompetitivo"),"Sin puntitos dibujados "+count);for(int i=0;i<count-1;i++)Check(actors[i].anchoredPosition.y-actors[i+1].anchoredPosition.y==PresentacionCaballoCarrera.SeparacionCarriles,"Carriles separados "+count+"/"+i);
 Check(actors.All(a=>a.anchoredPosition.y>=0&&a.anchoredPosition.y+148<world.rect.height),"Todos caben verticalmente "+count);
 foreach(var size in new[]{new Vector2Int(1920,1080),new Vector2Int(1600,900),new Vector2Int(1366,768),new Vector2Int(1280,720)})Render(ui,"previa-"+count,size);
 int cash=g.dinero;ui.IniciarCarrera();Check(g.dinero==cash-race.inscripcion,"Cobro al iniciar "+count);ui.IniciarCarrera();Check(g.dinero==cash-race.inscripcion,"Cobro único "+count);
 var arrow=actors[1].Find("IndicadorJugador");Check(arrow!=null&&actors.Where((a,i)=>i!=1).All(a=>a.Find("IndicadorJugador")==null),"Flecha ID real fuera del centro "+count);Call(ui,"ActualizarPresentacion",0f,false);Check(arrow.gameObject.activeSelf,"Flecha inicial "+count);Call(ui,"ActualizarPresentacion",2.01f,false);Check(!arrow.gameObject.activeSelf,"Dos segundos "+count);Call(ui,"ActualizarPresentacion",.01f,true);Check(arrow.gameObject.activeSelf,"A mantenida "+count);Call(ui,"ActualizarPresentacion",.01f,false);Check(!arrow.gameObject.activeSelf,"Soltar A "+count);
 if(count==6){for(int frame=0;frame<8;frame++){foreach(var a in anim){typeof(HorseVisualAnimator).GetField("elapsed",F).SetValue(a,frame/a.Profile.framesPerSecond+.01f-Time.deltaTime);Call(a,"Update");}Call(ui,"ActualizarPresentacion",0f,true);Render(ui,"fase-"+frame,new Vector2Int(1600,900));}}
 var order=(ClasificacionCarrera)Get(ui,"clasificacion");bool intermediate=false;for(int tick=0;tick<30000&&!order.Completa;tick++){Call(ui,"AvanzarCarrera",.02f);Call(ui,"ActualizarPresentacion",.02f,false);if(order.Resultados.Count>0&&!order.Completa){if(!intermediate&&count==6)Render(ui,"primero-en-meta",new Vector2Int(1600,900));intermediate=true;Check((bool)Get(ui,"carreraActiva"),"Continúa después del primero "+count);}}
 Check(intermediate&&order.Completa&&race.clasificacionFinal.Count==count&&race.clasificacionFinal.All(r=>r.Finalizo),"Todos llegan y ranking completo "+count);Check(ClasificacionCarrera.Validar(race,race.clasificacionFinal),"Clasificación válida "+count);Check(anim.All(a=>!a.IsRunning&&a.GetComponentInChildren<Image>(true).sprite==a.Profile.runFrames[2]),"Llegada conserva referencia "+count);Check(actors.All(a=>Mathf.Abs(a.anchoredPosition.x-map.meta)<.01f)&&world.Find("Meta").GetComponent<RectTransform>().anchoredPosition.x==map.meta,"Meta gráfica y competitiva coinciden "+count);int paid=g.dinero;g.FinalizarCarreraProgramada(race,g.CrearVistaParticipante(own),null);Check(paid==g.dinero&&g.dia==2,"Premio y día una sola vez "+count);if(count==6)Render(ui,"clasificacion",new Vector2Int(1600,900));}
 g.VolverAlHub();yield return null;g.IniciarNuevaPartida();Check(g.ElegirCarrera(g.ObtenerOfertaCarreras()[0].id,out _),"Prepara bloqueo Game Over");UIManager.instance.viewCarrera.GetComponentInChildren<CarreraUI>(true).enabled=true;g.SetState(Interactable.Tipo.TV);yield return null;var blocked=UIManager.instance.viewCarrera.GetComponentInChildren<CarreraUI>();blocked.enabled=false;blocked.IniciarCarrera();Call(blocked,"AvanzarCarrera",.2f);var states=(List<EstadoCaballoCarrera>)Get(blocked,"estadosCarrera");var progress=states.Select(x=>x.distanciaRecorrida).ToArray();g.dinero=-1;Check(g.GuardarPartida()&&g.Derrotado,"Saldo negativo confirmado durante carrera");Call(blocked,"AvanzarCarrera",10f);Check(progress.SequenceEqual(states.Select(x=>x.distanciaRecorrida))&&g.dia==1&&g.UltimoResultadoCarrera==null,"Game Over congela carrera sin premio ni avance de día");Debug.Log("ESCALA PRESENTACION PASS: "+checks.Count);
 }
 static object Get(object o,string n)=>o.GetType().GetField(n,F).GetValue(o);
 static object Call(object o,string n,params object[] args)=>o.GetType().GetMethod(n,F).Invoke(o,args);
 static void Check(bool v,string s){if(!v)throw new Exception(s);checks.Add(s);}
 static void Render(CarreraUI ui,string name,Vector2Int size){var camera=new GameObject("RenderPrueba").AddComponent<Camera>();camera.transform.position=new Vector3(0,0,-100);var canvases=Object.FindObjectsByType<Canvas>(FindObjectsSortMode.None).Where(c=>c.isRootCanvas).ToArray();var modes=canvases.Select(c=>c.renderMode).ToArray();var cams=canvases.Select(c=>c.worldCamera).ToArray();for(int i=0;i<canvases.Length;i++){canvases[i].renderMode=RenderMode.ScreenSpaceCamera;canvases[i].worldCamera=camera;canvases[i].planeDistance=1;}var rt=new RenderTexture(size.x,size.y,24);camera.targetTexture=rt;Canvas.ForceUpdateCanvases();var hs=(List<Caballo>)Get(ui,"caballosData");var own=(Caballo)Get(ui,"caballoJugadorParticipante");var ac=(List<RectTransform>)Get(ui,"caballosUI");var order=(ClasificacionCarrera)Get(ui,"clasificacion");Call(Get(ui,"pista"),"Actualizar",0f,ac[hs.FindIndex(h=>h.id==own.id)].anchoredPosition.x,order?.Resuelto(own.id)==true,true);Canvas.ForceUpdateCanvases();camera.Render();RenderTexture.active=rt;var t=new Texture2D(size.x,size.y,TextureFormat.RGB24,false);t.ReadPixels(new Rect(0,0,size.x,size.y),0,0);t.Apply();File.WriteAllBytes(O+name+"-"+size.x+"x"+size.y+".png",t.EncodeToPNG());RenderTexture.active=null;camera.targetTexture=null;for(int i=0;i<canvases.Length;i++){canvases[i].renderMode=modes[i];canvases[i].worldCamera=cams[i];}Object.Destroy(camera.gameObject);Object.Destroy(t);Object.Destroy(rt);Check(true,"Render "+name+" "+size);}
 static void End(int code){SessionState.SetBool(K,false);File.WriteAllLines(O+"escala-pruebas.txt",checks);EditorApplication.Exit(code);}
}
